const out = {components:[], fonts:new Set(), pages:[]};
for (const p of figma.root.children) {
  const comps = p.findAll(n => n.type === 'COMPONENT');
  out.pages.push({id:p.id, name:p.name, count:comps.length});
  for (const c of comps) {
    const rec = {id:c.id, name:c.name, page:p.name, w:c.width, h:c.height, children:[]};
    for (const ch of c.children) {
      const fills = (ch.fills && ch.fills.length) ? ch.fills.map(f => f.type==='SOLID' ? '#'+[f.color.r,f.color.g,f.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('')+(f.opacity!==undefined?('@'+f.opacity):'') : f.type).join(',') : null;
      rec.children.push({type:ch.type, name:ch.name, w:Math.round(ch.width), h:Math.round(ch.height), fills});
      if (ch.type === 'TEXT') ch.getRangeAllFontNames(0, ch.characters.length).forEach(f => out.fonts.add(f.family+'|'+f.style));
    }
    if (c.type === 'COMPONENT') {
      try { c.findAll(n=>n.type==='TEXT').forEach(t => { if(t.characters) t.getRangeAllFontNames(0,t.characters.length).forEach(f=>out.fonts.add(f.family+'|'+f.style)); }); } catch(e){}
    }
    out.components.push(rec);
  }
}
out.fonts = Array.from(out.fonts);
return out;

