function post(parent,y,author,init,verified,date,time,body,liked){
  const card=frame(parent,'post '+author,20,y,335,236,C.white,20);
  card.strokes=[{...solid(C.line)}];card.strokeWeight=1;card.strokeAlign='INSIDE';
  const av=frame(card,'avatar',16,16,44,44,'#E9E7F3',22);
  txt(av,init,0,12,{size:13,weight:'SemiBold',color:'#7B74A8',w:44,align:'CENTER'});
  txt(card,author,68,16,{size:13,weight:'SemiBold'});
  if(verified)inst(card,'2:23',68+author.length*7.6+6,19,14);
  txt(card,date+' · '+time,68,36,{size:9.5,color:C.muted});
  const more=inst(card,'2:18',295,20,18);recolor(more,C.muted);
  const topic=frame(card,'topic tag',16,68,86,22,C.deepSoft,11);
  txt(topic,'Personal finance',0,4,{size:9,weight:'SemiBold',color:C.deep,w:86,align:'CENTER'});
  txt(card,body,16,98,{size:11.5,color:C.ink2,w:303,lh:18});
  const bar=frame(card,'engagement',16,192,303,28,null);
  const cm=[['2:20','12 Comments'],['2:21','160 Likes'],['2:22','0 Dislikes']];
  let ex=0;
  cm.forEach(([ic,label],i)=>{
    const g=frame(bar,'eng '+i,ex,0,label.length*5.4+22,28,null);
    const ii=inst(g,ic,0,i===0?6:5,14);
    const isLike=i===1&&liked;
    recolor(ii, isLike? C.deep : (i===0?C.ink2:C.ink2));
    if(isLike){ii.opacity=1;}
    txt(g,label,19,i===0?7:6,{size:9.5,weight:isLike?'SemiBold':'Regular',color:isLike?C.deep:C.muted});
    ex+=g.width+16;
  });
  if(liked){const likeDot=frame(card,'liked bg',0,0,10,10,null);likeDot.remove();}
  return card;
}
