function txt(p,ch,x,y,o={}){const t=figma.createText();p.appendChild(t);t.fontName={family:'Plus Jakarta Sans',style:o.weight||'Regular'};t.characters=ch;t.fontSize=o.size||14;t.fills=[solid(o.color||C.ink)];t.lineHeight={value:o.lh||Math.round((o.size||14)*1.45),unit:'PIXELS'};t.x=x;t.y=y;if(o.w){t.resize(o.w,t.height);t.textAutoResize='HEIGHT';t.textAlignHorizontal=o.align||'LEFT';}else if(o.align)t.textAlignHorizontal=o.align;return t;}
function circle(p,x,y,d,fill){const e=figma.createEllipse();p.appendChild(e);e.x=x;e.y=y;e.resize(d,d);e.fills=[solid(fill)];return e;}

