  out[n]={id:f.id,size:[f.width,f.height],hits:[...seen.values()].map(h=>({n:h.name.replace('hit · ',''),dest:h.reactions&&h.reactions[0]?h.reactions[0].actions[0].destinationId:null}))};
}
return out;

